    const remindLater = page.getByRole("button", { name: "Remind Later" });
    if (await remindLater.isVisible().catch(() => false)) {
        await remindLater.click();
    }

    const fieldRows = page.locator('.field-grid .field-select');
    const fieldNames = page.locator('.field-grid .field-select .name');
    const dragHandles = page.locator('.field-grid .field-select .drag-handle');
    await fieldNames.first().waitFor({ state: 'visible', timeout: 20000 });

    // Before the drag: the four top-level fields render in their saved sort order.
    await expect(fieldNames).toHaveCount(4);
    await expect(fieldNames.nth(0)).toHaveText('id');
    await expect(fieldNames.nth(1)).toHaveText('alpha');
    await expect(fieldNames.nth(2)).toHaveText('bravo');
    await expect(fieldNames.nth(3)).toHaveText('charlie');

    // Drag the "alpha" row by its handle down past "charlie".
    const sourceHandle = (await dragHandles.nth(1).boundingBox())!;
    const dropTarget = (await fieldRows.nth(3).boundingBox())!;
    await page.mouse.move(sourceHandle.x + sourceHandle.width / 2, sourceHandle.y + sourceHandle.height / 2);
    await page.mouse.down();
    await page.mouse.move(sourceHandle.x + sourceHandle.width / 2, sourceHandle.y + sourceHandle.height / 2 + 10, { steps: 5 });
    await page.mouse.move(sourceHandle.x + sourceHandle.width / 2, dropTarget.y + dropTarget.height * 0.75, { steps: 25 });
